"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72981"],{16137(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.origem_igual_ao_destino","status":422,"titulo":"Uma modalidade n\xe3o pode remanejar para si mesma"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.origem_igual_ao_destino","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["`modalidadeOrigemCodigo` e `modalidadeDestinoCodigo` de uma posi\xe7\xe3o da\\ncascata s\xe3o o mesmo c\xf3digo. Remanejar uma vaga n\xe3o preenchida para a\\npr\xf3pria modalidade de origem n\xe3o \xe9 remanejamento nenhum \u2014 a vaga\\nsimplesmente continuaria n\xe3o preenchida.","S\xf3 \xe9 conferida depois de os dois c\xf3digos j\xe1 terem passado individualmente\\npor\\n[`codigo_invalido`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido)\\n\u2014 por isso nunca coexiste com ela no mesmo item: se um dos dois c\xf3digos j\xe1\\nestiver fora do vocabul\xe1rio, a compara\xe7\xe3o entre eles n\xe3o roda. Pode\\ncoexistir com\\n[`ordem_invalida`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_invalida)\\ndo mesmo item (confer\xeancias independentes, ADR-0125) e com os mesmos erros de\\noutros itens da lista `destinos`."],"comoResolver":["Corrija `modalidadeDestinoCodigo` (ou `modalidadeOrigemCodigo`) para uma\\nmodalidade diferente. Se a inten\xe7\xe3o era declarar que a modalidade n\xe3o\\nremaneja \u2014 fica com a vaga vazia at\xe9 o fallback \u2014, remova a posi\xe7\xe3o da\\ncascata em vez de apont\xe1-la para si mesma."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);